const crypto = require('crypto');
const input = $json.body ?? $json;
const expectedStages = ['chat','workflows','code','projects','skills'];
const next = {chat:'workflows',workflows:'code',code:'projects',projects:'skills',skills:'chat'};
const requiredEvidence = new Set(['code:projects','projects:skills','skills:chat']);
const origins = new Set(['founder-native','repo-native','generated','provider','community','vendor']);
const authorityRank = {reason:0,draft:1,reversible:2,privileged:3};
const originCeiling = {'founder-native':'privileged','repo-native':'privileged',generated:'draft',provider:'draft',community:'draft',vendor:'draft'};
const planFields = new Set(['contract','selectedBy','goal','projectSlug','expectedHeadSha','registryHash','requestedAuthority','strategicLenses','routingReason','capabilities','proofRequirements','outcomeSignals','rollback','planHash']);
const capabilityFields = new Set(['id','version','origin','owner','sourceHash','authorityCeiling']);
const fail = (reason) => { throw new Error(reason); };
const text = (value) => typeof value === 'string' ? value.trim() : '';
const uniq = (values) => [...new Set(values.map(text).filter(Boolean))].sort();
const sha256 = (value) => crypto.createHash('sha256').update(value).digest('hex');
const record = (value) => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const onlyFields = (value, allowed) => record(value) && Object.keys(value).every((key) => allowed.has(key));
const normalizedRequiredStrings = (value, label) => { if (!Array.isArray(value) || !value.every((item) => typeof item === 'string') || value.some((item) => !text(item))) fail(`${label} required`); const normalized = uniq(value); if (normalized.length === 0) fail(`${label} required`); return normalized; };
if (input.contract !== 'founder-control-room/n8n-conveyor@v3') fail('invalid contract');
if (input.event !== 'conveyor.stage.advance') fail('invalid event');
if (!/^fcr-conveyor-v3:[0-9a-f]{64}$/i.test(input.idempotencyKey ?? '')) fail('invalid idempotency key');
if (!text(input.runId)) fail('runId required');
if (!text(input.projectSlug)) fail('projectSlug required');
if (!text(input.goal)) fail('goal required');
if (!/^[0-9a-f]{40}$/i.test(input.expectedHeadSha ?? '')) fail('expectedHeadSha must be exact');
if (!expectedStages.includes(input.fromStage) || !expectedStages.includes(input.toStage)) fail('invalid stage');
if (next[input.fromStage] !== input.toStage) fail('invalid stage transition');
const evidenceUrls = Array.isArray(input.evidenceUrls) ? uniq(input.evidenceUrls) : fail('evidenceUrls must be an array');
const validPort = (value) => { if (value === '') return true; if (!/^\d{1,5}$/.test(value)) return false; const port = Number(value); return port >= 1 && port <= 65535; };
const validHost = (value) => { if (!value || value.length > 253) return false; if (/^\d+(?:\.\d+){3}$/.test(value)) return value.split('.').every((part) => /^\d{1,3}$/.test(part) && Number(part) <= 255); return /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(value); };
const validEvidenceUrl = (value) => { if (/\s/.test(value)) return false; const match = value.match(/^(https?):\/\/([^/?#]+)(?:[/?#][^\s]*)?$/i); if (!match) return false; const protocol = match[1].toLowerCase(); const authority = match[2]; if (authority.includes('@') || authority.startsWith('[')) return false; const colonIndex = authority.lastIndexOf(':'); let host = authority; let port = ''; if (colonIndex !== -1) { if (authority.indexOf(':') !== colonIndex) return false; host = authority.slice(0, colonIndex); port = authority.slice(colonIndex + 1); if (!port) return false; } if (!validHost(host) || !validPort(port)) return false; return protocol === 'https' || (protocol === 'http' && (host.toLowerCase() === 'localhost' || host === '127.0.0.1')); };
for (const value of evidenceUrls) if (!validEvidenceUrl(value)) fail('invalid evidence URL');
if (requiredEvidence.has(`${input.fromStage}:${input.toStage}`) && evidenceUrls.length === 0) fail('evidence required');
const authority = input.authority ?? {};
if (authority.advanceStage !== true || authority.merge !== false || authority.deploy !== false || authority.publish !== false || authority.sendExternal !== false) fail('authority envelope rejected');
const plan = input.capabilityPlan;
if (!record(plan)) fail('Chief AI capability plan required');
if (!onlyFields(plan, planFields)) fail('unsupported capability plan field');
if (plan.contract !== 'juss-v10/capability-plan@v1') fail('invalid capability plan contract');
if (plan.selectedBy !== 'chief-ai-machine') fail('capability selection must be owned by Chief AI Machine');
if (text(plan.goal) !== text(input.goal)) fail('capability plan goal mismatch');
if (text(plan.projectSlug) !== text(input.projectSlug)) fail('capability plan project mismatch');
if (text(plan.expectedHeadSha).toLowerCase() !== text(input.expectedHeadSha).toLowerCase()) fail('capability plan head mismatch');
if (!/^[0-9a-f]{64}$/i.test(text(plan.registryHash))) fail('invalid registry hash');
if (!/^[0-9a-f]{64}$/i.test(text(plan.planHash))) fail('invalid capability plan hash');
if (!['reason','draft'].includes(plan.requestedAuthority)) fail('capability plan authority exceeds conveyor envelope');
const strategicLenses = normalizedRequiredStrings(plan.strategicLenses, 'strategic lenses');
if (!text(plan.routingReason)) fail('routing reason required');
const proofRequirements = normalizedRequiredStrings(plan.proofRequirements, 'proof requirements');
const outcomeSignals = normalizedRequiredStrings(plan.outcomeSignals, 'outcome signals');
if (!text(plan.rollback)) fail('rollback required');
if (!Array.isArray(plan.capabilities) || plan.capabilities.length === 0 || plan.capabilities.length > 30) fail('invalid capabilities');
const ids = new Set();
for (const capability of plan.capabilities) {
  if (!onlyFields(capability, capabilityFields)) fail('unsupported capability field');
  if (!text(capability.id) || !text(capability.version) || !text(capability.owner)) fail('invalid capability identity');
  if (ids.has(text(capability.id))) fail('duplicate capability id'); ids.add(text(capability.id));
  if (!origins.has(capability.origin)) fail('invalid capability origin');
  if (!/^[0-9a-f]{64}$/i.test(text(capability.sourceHash))) fail('invalid capability source hash');
  if (!(capability.authorityCeiling in authorityRank)) fail('invalid capability authority ceiling');
  if (authorityRank[capability.authorityCeiling] > authorityRank[originCeiling[capability.origin]]) fail('capability origin authority exceeded');
  if (authorityRank[plan.requestedAuthority] > authorityRank[capability.authorityCeiling]) fail('capability cannot satisfy requested authority');
}
const sortedCapabilities = [...plan.capabilities].sort((a,b) => text(a.id).localeCompare(text(b.id)));
const planSeed = JSON.stringify([plan.contract,plan.selectedBy,text(plan.goal),text(plan.projectSlug),text(plan.expectedHeadSha).toLowerCase(),text(plan.registryHash).toLowerCase(),plan.requestedAuthority,strategicLenses,text(plan.routingReason),sortedCapabilities.map((capability)=>[text(capability.id),text(capability.version),capability.origin,text(capability.owner),text(capability.sourceHash).toLowerCase(),capability.authorityCeiling]),proofRequirements,outcomeSignals,text(plan.rollback)]);
if (sha256(planSeed) !== text(plan.planHash).toLowerCase()) fail('capability plan hash mismatch');
const expectedIdempotency = `fcr-conveyor-v3:${sha256([text(input.runId),text(input.projectSlug),input.fromStage,input.toStage,text(input.expectedHeadSha).toLowerCase(),text(plan.planHash).toLowerCase()].join(':'))}`;
if (text(input.idempotencyKey).toLowerCase() !== expectedIdempotency) fail('idempotency key does not match capability plan');
const skillIds = uniq(plan.capabilities.map((capability) => capability.id));
const receiptSeed = JSON.stringify([text(input.idempotencyKey),text(input.runId),text(input.projectSlug),text(input.goal),text(input.expectedHeadSha).toLowerCase(),input.fromStage,input.toStage,text(plan.planHash).toLowerCase(),text(plan.registryHash).toLowerCase(),skillIds,evidenceUrls]);
return [{json:{accepted:true,receiptSeed,contract:'founder-control-room/n8n-conveyor@v3',event:'conveyor.stage.accepted',idempotencyKey:text(input.idempotencyKey),runId:text(input.runId),projectSlug:text(input.projectSlug),fromStage:input.fromStage,toStage:input.toStage,expectedHeadSha:text(input.expectedHeadSha).toLowerCase(),capabilityPlanHash:text(plan.planHash).toLowerCase(),registryHash:text(plan.registryHash).toLowerCase(),skillIds,outcomeSignals,evidenceUrls}}];

const crypto = require('crypto');
const receiptId = `fcr-conveyor-receipt-v3:${crypto.createHash('sha256').update($json.receiptSeed).digest('hex')}`;
return [{json:{receiptId,status:'accepted',contract:$json.contract,event:$json.event,idempotencyKey:$json.idempotencyKey,runId:$json.runId,projectSlug:$json.projectSlug,fromStage:$json.fromStage,toStage:$json.toStage,expectedHeadSha:$json.expectedHeadSha,capabilityPlanHash:$json.capabilityPlanHash,registryHash:$json.registryHash,skillIds:$json.skillIds,outcomeSignals:$json.outcomeSignals,evidenceUrls:$json.evidenceUrls}}];
